def faq(q,a): return {'q':q,'a':a}
def module(k,t,b,pts): return {'kicker':k,'title':t,'body':b,'points':pts}
def step(t,b): return {'title':t,'body':b}
def ed(t,ps): return {'title':t,'paragraphs':ps}
def comp(l,t,b): return {'label':l,'title':t,'body':b}
def metric(v,l,n): return {'value':v,'label':l,'note':n}
def kpi(m,meaning): return {'metric':m,'meaning':meaning}

